    """
    # Check if the encoded and original strings are the same length
    if len(encoded) != len(original):
        return "Failed"

    # Build a dictionary mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

